/* @lc app=leetcode id=985 lang=kotlin */ class Solution { fun sumEvenAfterQueries(nums: IntArray, queries: Array<IntArray>): IntArray = queries.fold(nums.filter { it % 2 == 0 }.sum() to listOf<Int>()) { (s, r), (v, i) -> (if (nums[i] % 2 == 0) s - nums[i] else s).let { s1 -> nums.also { it[i] += v }.let { if (it[i] % 2 == 0) s1 + it[i] else s1 } }.let { t -> t to r + t } }.second.toIntArray() }